package com.tekwatt.admin.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="platform_settings",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","setting_key"}))public class PlatformSetting{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,length=80)private String settingKey;@Column(columnDefinition="TEXT")private String settingValue;@Column(nullable=false)private Instant updatedAt;protected PlatformSetting(){}public PlatformSetting(UUID t,String k){id=UUID.randomUUID();tenantId=t;settingKey=k;}public void value(String v){settingValue=v;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getSettingKey(){return settingKey;}public String getSettingValue(){return settingValue;}public Instant getUpdatedAt(){return updatedAt;}}
